const crypto = require('crypto');
const req = $input.first().json;
const sig = String(req.headers['x-lendloop-signature'] || '');
const ts = String(req.headers['x-lendloop-timestamp'] || '');
if (!ts || Math.abs(Date.now() - Number(ts)) > 5 * 60 * 1000) throw new Error('Stale or missing timestamp');
const expected = crypto.createHmac('sha256', $env.LENDLOOP_WEBHOOK_SECRET).update(ts + '.' + JSON.stringify(req.body)).digest('hex');
const a = Buffer.from(expected), b = Buffer.from(sig);
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) throw new Error('Invalid signature');
return [{ json: req.body }];

const e = $input.first().json;
const t = {
  request_created: `New request for your ${e.toolName} (${e.startDate} to ${e.endDate}).`,
  request_approved: `Your request for ${e.toolName} was approved (${e.startDate} to ${e.endDate}).`,
  request_declined: `Your request for ${e.toolName} was declined.`,
  loan_returned: `${e.toolName} has been marked as returned. Thanks!`
};
const msg = t[e.type];
if (!msg) throw new Error('Unknown event type: ' + e.type);
// MOCK NOTIFICATION: swap for a Send Email / Slack node. Only name+email are available here by design.
console.log(`[notify] to=${e.recipient.email} :: ${msg} (event ${e.eventId})`);
return [{ json: { to: e.recipient.email, message: msg, eventId: e.eventId } }];
